export function threeSum(values          )             {
  const sorted=[...values].sort((a,b)=>a-b), result            =[]; for(let i=0;i<sorted.length-2;i++) { if(i>0&&sorted[i]===sorted[i-1]) continue; let left=i+1,right=sorted.length-1; while(left<right) { const sum=sorted[i]+sorted[left]+sorted[right]; if(sum<0) left++; else if(sum>0) right--; else { result.push([sorted[i],sorted[left],sorted[right]]); const a=sorted[left],b=sorted[right]; while(left<right&&sorted[left]===a) left++; while(left<right&&sorted[right]===b) right--; } } } return result;
}

